DO $$ BEGIN IF inet_server_addr() IS DISTINCT FROM '127.0.0.1'::inet AND inet_server_addr() IS DISTINCT FROM '::1'::inet THEN RAISE EXCEPTION 'Local SQL tests require loopback PostgreSQL'; END IF; END $$;
SET ROLE authenticated;
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
INSERT INTO test_auth.fixture SELECT 'rejoin_invite',public.create_workspace_invitation('20000000-0000-4000-8000-000000000002','Rejoining technician','fixture3@example.invalid',ARRAY['tecnico']);
SELECT test_auth.login(3);
SELECT public.accept_workspace_invitation((SELECT id FROM test_auth.fixture WHERE name='rejoin_invite'));
SELECT test_auth.login(3,'20000000-0000-4000-8000-000000000002');
SELECT test_auth.assert((SELECT is_technician FROM public.get_current_actor_context()),'fresh invitation reactivates revoked employee membership');
SELECT test_auth.assert((public.get_my_access_context('20000000-0000-4000-8000-000000000002')->>'employee_id')::uuid<>(SELECT id FROM test_auth.fixture WHERE name='tech_employee'),'new employee ID selected; old assignment preserved');
SELECT test_auth.login(2,'20000000-0000-4000-8000-000000000002');
INSERT INTO test_auth.fixture SELECT 'delivery_invite',public.create_workspace_invitation('20000000-0000-4000-8000-000000000002','Delivery fixture','delivery@example.invalid',ARRAY['atendente']);
SELECT test_auth.expect_error('SELECT public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000002'')','42501');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',false);
SET ROLE service_role;
SELECT test_auth.expect_error('SELECT public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000006'')','42501');
INSERT INTO test_auth.fixture SELECT 'delivery_claim',(public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name='delivery_invite'),'10000000-0000-4000-8000-000000000002')->>'delivery_attempt_id')::uuid;
SELECT test_auth.expect_error('SELECT public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000002'')','PT429');
SELECT test_auth.expect_error('SELECT public.mark_invitation_delivery((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000002'',''00000000-0000-4000-8000-000000000000'',true)','22023');
SELECT public.mark_invitation_delivery((SELECT id FROM test_auth.fixture WHERE name='delivery_invite'),'10000000-0000-4000-8000-000000000002',(SELECT id FROM test_auth.fixture WHERE name='delivery_claim'),false,'SMTP_NOT_CONFIGURED');
RESET ROLE;
SELECT test_auth.assert((SELECT delivery_attempts=1 AND last_delivery_status='failed' AND last_delivery_error_code='SMTP_NOT_CONFIGURED' FROM public.workspace_invitations WHERE id=(SELECT id FROM test_auth.fixture WHERE name='delivery_invite')),'delivery attempts count reservation once; failed config recorded safely');
UPDATE public.workspace_invitations SET last_delivery_attempt_at=clock_timestamp()-interval '3 minutes' WHERE id=(SELECT id FROM test_auth.fixture WHERE name='delivery_invite');
SET ROLE service_role;
INSERT INTO test_auth.fixture SELECT 'delivery_claim_2',(public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name='delivery_invite'),'10000000-0000-4000-8000-000000000002')->>'delivery_attempt_id')::uuid;
SELECT test_auth.expect_error('SELECT public.mark_invitation_delivery((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000002'',(SELECT id FROM test_auth.fixture WHERE name=''delivery_claim''),true)','22023');
SELECT public.mark_invitation_delivery((SELECT id FROM test_auth.fixture WHERE name='delivery_invite'),'10000000-0000-4000-8000-000000000002',(SELECT id FROM test_auth.fixture WHERE name='delivery_claim_2'),true,NULL);
RESET ROLE;
SELECT test_auth.assert((SELECT delivery_attempts=2 AND last_delivery_status='queued' FROM public.workspace_invitations WHERE id=(SELECT id FROM test_auth.fixture WHERE name='delivery_invite')),'accepted by sender is queued, never delivered');
SELECT set_config('request.jwt.claims','{}',false);
SET ROLE service_role;
SELECT test_auth.expect_error('SELECT public.get_invitation_delivery_details((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''),''10000000-0000-4000-8000-000000000002'')','42501');
RESET ROLE;
SELECT 'PASS: reinvitation, server-only delivery, atomic lease/cooldown, stale claim and safe failed configuration' AS result;
